import{_ as t,o as r,c as a,a2 as d}from"./chunks/framework.vLhlLNVn.js";const p=JSON.parse('{"title":"API Reference","description":"","frontmatter":{},"headers":[],"relativePath":"api-reference/index.md","filePath":"api-reference/index.md"}'),o={name:"api-reference/index.md"};function c(i,e,n,s,h,l){return r(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="api-reference" tabindex="-1">API Reference <a class="header-anchor" href="#api-reference" aria-label="Permalink to &quot;API Reference&quot;">​</a></h1><p>Every method of skapi-swift 2.4.0. <code>Skapi</code> is an actor: each call is <code>try await</code>. Each one throws <a href="/introduction/errors.html"><code>SkapiError</code></a> on failure. What skapi-js has and this SDK leaves out is listed in <a href="/introduction/not-included.html">Not Included</a>.</p><h2 id="connection" tabindex="-1"><a href="/api-reference/connection.html">Connection</a> <a class="header-anchor" href="#connection" aria-label="Permalink to &quot;[Connection](/api-reference/connection)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>method</th><th></th></tr></thead><tbody><tr><td><a href="/api-reference/connection.html#skapi"><code>Skapi(projectId:storage:timeout:targetCDN:encryption:urlSession:observeAppLifecycle:)</code></a></td><td>connects to one project</td></tr><tr><td><a href="/api-reference/connection.html#getconnectioninfo"><code>getConnectionInfo(refresh:)</code></a></td><td>project name and settings</td></tr><tr><td><a href="/api-reference/connection.html#appdidreturn"><code>appDidReturn()</code></a></td><td>tells the SDK the app came back to the foreground</td></tr><tr><td><a href="/api-reference/connection.html#storage"><code>SkapiStorage</code>, <code>KeychainStorage</code>, <code>MemoryStorage</code>, <code>FileStorage</code></a></td><td>where the session is kept</td></tr><tr><td><a href="/api-reference/connection.html#fetchoptions"><code>FetchOptions</code></a></td><td>paging</td></tr><tr><td><a href="/api-reference/connection.html#json"><code>JSON</code></a></td><td>the value type of data, queries and answers</td></tr><tr><td><a href="/api-reference/connection.html#skapierror"><code>SkapiError</code></a></td><td>the error every method throws</td></tr></tbody></table><h2 id="authentication" tabindex="-1"><a href="/api-reference/authentication.html">Authentication</a> <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;[Authentication](/api-reference/authentication)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>method</th><th></th></tr></thead><tbody><tr><td><a href="/api-reference/authentication.html#signup"><code>signup(_:option:)</code></a></td><td>creates an account</td></tr><tr><td><a href="/api-reference/authentication.html#resendsignupconfirmation"><code>resendSignupConfirmation()</code></a></td><td>sends the confirmation e-mail again</td></tr><tr><td><a href="/api-reference/authentication.html#login"><code>login(email:username:password:)</code></a></td><td>signs in</td></tr><tr><td><a href="/api-reference/authentication.html#verifymfa"><code>verifyMFA(code:)</code></a></td><td>finishes a login that needs an authenticator code</td></tr><tr><td><a href="/api-reference/authentication.html#logout"><code>logout(global:)</code></a></td><td>signs out</td></tr><tr><td><a href="/api-reference/authentication.html#getprofile"><code>getProfile(refreshToken:)</code></a></td><td>the signed-in user&#39;s profile</td></tr><tr><td><a href="/api-reference/authentication.html#loginwithtoken"><code>loginWithToken(idToken:accessToken:refreshToken:)</code></a></td><td>adopts tokens from another sign-in</td></tr><tr><td><a href="/api-reference/authentication.html#updateprofile"><code>updateProfile(_:)</code></a></td><td>changes the user&#39;s profile</td></tr><tr><td><a href="/api-reference/authentication.html#changepassword"><code>changePassword(currentPassword:newPassword:)</code></a></td><td>changes the password</td></tr><tr><td><a href="/api-reference/authentication.html#forgotpassword"><code>forgotPassword(email:template:)</code></a></td><td>sends a password reset code</td></tr><tr><td><a href="/api-reference/authentication.html#resetpassword"><code>resetPassword(email:code:newPassword:)</code></a></td><td>sets a new password with the code</td></tr><tr><td><a href="/api-reference/authentication.html#verifyemail"><code>verifyEmail(code:template:)</code></a></td><td>sends or checks an e-mail verification code</td></tr><tr><td><a href="/api-reference/authentication.html#lastverifiedemail"><code>lastVerifiedEmail(revert:)</code></a></td><td>the last verified e-mail</td></tr><tr><td><a href="/api-reference/authentication.html#disableaccount"><code>disableAccount()</code></a></td><td>disables the user&#39;s own account</td></tr><tr><td><a href="/api-reference/authentication.html#recoveraccount"><code>recoverAccount(redirect:)</code></a></td><td>sends the recovery e-mail to a disabled account</td></tr><tr><td><a href="/api-reference/authentication.html#openidlogin"><code>openIdLogin(token:id:merge:template:)</code></a></td><td>signs in through an OpenID provider</td></tr><tr><td><a href="/api-reference/authentication.html#anonymouslogin"><code>anonymousLogin()</code></a></td><td>a temporary account without e-mail or password</td></tr><tr><td><a href="/api-reference/authentication.html#verifyanonymoussession"><code>verifyAnonymousSession()</code></a></td><td>checks a restored temporary account still exists</td></tr><tr><td><a href="/api-reference/authentication.html#setupmfa"><code>setupMFA(issuer:accountName:)</code></a> / <a href="/api-reference/authentication.html#enablemfa"><code>enableMFA(code:)</code></a> / <a href="/api-reference/authentication.html#disablemfa"><code>disableMFA()</code></a> / <a href="/api-reference/authentication.html#getmfastatus"><code>getMFAStatus()</code></a></td><td>two-step login with an authenticator app</td></tr></tbody></table><h2 id="database" tabindex="-1"><a href="/api-reference/database.html">Database</a> <a class="header-anchor" href="#database" aria-label="Permalink to &quot;[Database](/api-reference/database)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>method</th><th></th></tr></thead><tbody><tr><td><a href="/api-reference/database.html#postrecord"><code>postRecord(_:config:files:)</code></a></td><td>creates or updates a record</td></tr><tr><td><a href="/api-reference/database.html#postrecords"><code>postRecords(_:)</code></a></td><td>many records in few requests</td></tr><tr><td><a href="/api-reference/database.html#getrecords"><code>getRecords(_:fetchOptions:)</code></a></td><td>reads records</td></tr><tr><td><a href="/api-reference/database.html#deleterecords"><code>deleteRecords(_:fetchOptions:)</code></a></td><td>deletes records</td></tr><tr><td><a href="/api-reference/database.html#gettables"><code>getTables</code></a> / <a href="/api-reference/database.html#gettags"><code>getTags</code></a> / <a href="/api-reference/database.html#getindexes"><code>getIndexes</code></a> / <a href="/api-reference/database.html#getuniqueid"><code>getUniqueId</code></a></td><td>what the database holds</td></tr><tr><td><a href="/api-reference/database.html#uploadfiles"><code>uploadFiles(_:recordId:service:)</code></a></td><td>attaches files to a record</td></tr><tr><td><a href="/api-reference/database.html#getfile"><code>getFile</code></a> / <a href="/api-reference/database.html#getfiletext"><code>getFileText</code></a> / <a href="/api-reference/database.html#getfileendpoint"><code>getFileEndpoint</code></a> / <a href="/api-reference/database.html#getfileinfo"><code>getFileInfo</code></a> / <a href="/api-reference/database.html#downloadfile"><code>downloadFile</code></a></td><td>reads a file, or makes a link to it</td></tr><tr><td><a href="/api-reference/database.html#deletefiles"><code>deleteFiles(_:)</code></a></td><td>removes files from records</td></tr><tr><td><a href="/api-reference/database.html#grantprivaterecordaccess"><code>grantPrivateRecordAccess</code></a> / <a href="/api-reference/database.html#removeprivaterecordaccess"><code>removePrivateRecordAccess</code></a> / <a href="/api-reference/database.html#listprivaterecordaccess"><code>listPrivateRecordAccess</code></a> / <a href="/api-reference/database.html#requestprivaterecordaccesskey"><code>requestPrivateRecordAccessKey</code></a></td><td>sharing private records</td></tr></tbody></table><h2 id="encryption" tabindex="-1"><a href="/api-reference/encryption.html">Encryption</a> <a class="header-anchor" href="#encryption" aria-label="Permalink to &quot;[Encryption](/api-reference/encryption)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>method</th><th></th></tr></thead><tbody><tr><td><a href="/api-reference/encryption.html#encryptionoptions"><code>EncryptionOptions</code></a></td><td>turns encryption on, in <code>Skapi(projectId:encryption:)</code></td></tr><tr><td><a href="/api-reference/encryption.html#getencryptionstatus"><code>getEncryptionStatus()</code></a></td><td>locked, unlocked or disabled</td></tr><tr><td><a href="/api-reference/encryption.html#unlockencryption"><code>unlockEncryption(password:)</code></a> / <a href="/api-reference/encryption.html#lockencryption"><code>lockEncryption(forgetDevice:)</code></a></td><td>opens or forgets the user&#39;s keys</td></tr><tr><td><a href="/api-reference/encryption.html#unlockencryptionwithrecoverycode"><code>unlockEncryptionWithRecoveryCode(_:password:)</code></a> / <a href="/api-reference/encryption.html#regenerateencryptionrecoverycode"><code>regenerateEncryptionRecoveryCode()</code></a></td><td>encryption recovery codes (the first one is shown once in <code>getConnectionInfo()</code>)</td></tr><tr><td><a href="/api-reference/encryption.html#pinpeerkey"><code>pinPeerKey(userId:fingerprint:)</code></a></td><td>trusts another user&#39;s key for sharing</td></tr><tr><td><a href="/api-reference/encryption.html#iswithheld"><code>isWithheld(_:)</code></a></td><td>tells the placeholder of undecryptable data apart</td></tr></tbody></table><h2 id="users" tabindex="-1"><a href="/api-reference/users.html">Users</a> <a class="header-anchor" href="#users" aria-label="Permalink to &quot;[Users](/api-reference/users)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>method</th><th></th></tr></thead><tbody><tr><td><a href="/api-reference/users.html#getusers"><code>getUsers(_:fetchOptions:)</code></a></td><td>searches the project&#39;s users</td></tr><tr><td><a href="/api-reference/users.html#subscribe"><code>subscribe(_:)</code></a> / <a href="/api-reference/users.html#unsubscribe"><code>unsubscribe(_:)</code></a></td><td>subscribes to another user</td></tr><tr><td><a href="/api-reference/users.html#blocksubscriber"><code>blockSubscriber(_:)</code></a> / <a href="/api-reference/users.html#unblocksubscriber"><code>unblockSubscriber(_:)</code></a></td><td>blocks a subscriber</td></tr><tr><td><a href="/api-reference/users.html#getsubscriptions"><code>getSubscriptions(_:fetchOptions:)</code></a></td><td>who subscribes to whom</td></tr><tr><td><a href="/api-reference/users.html#getfeed"><code>getFeed(_:fetchOptions:)</code></a></td><td>records from the users you subscribe to</td></tr><tr><td><a href="/api-reference/users.html#subscribenewsletter"><code>subscribeNewsletter(_:)</code></a> / <a href="/api-reference/users.html#unsubscribenewsletter"><code>unsubscribeNewsletter(group:)</code></a></td><td>newsletter subscription</td></tr><tr><td><a href="/api-reference/users.html#getnewsletters"><code>getNewsletters(_:fetchOptions:)</code></a> / <a href="/api-reference/users.html#getnewslettersubscription"><code>getNewsletterSubscription(_:fetchOptions:)</code></a></td><td>sent newsletters and the user&#39;s subscriptions</td></tr><tr><td><a href="/api-reference/users.html#sendinquiry"><code>sendInquiry(_:)</code></a></td><td>sends a message to the project owner</td></tr></tbody></table><h2 id="realtime" tabindex="-1"><a href="/api-reference/realtime.html">Realtime</a> <a class="header-anchor" href="#realtime" aria-label="Permalink to &quot;[Realtime](/api-reference/realtime)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>method</th><th></th></tr></thead><tbody><tr><td><a href="/api-reference/realtime.html#connectrealtime"><code>connectRealtime(_:)</code></a> / <a href="/api-reference/realtime.html#closerealtime"><code>closeRealtime()</code></a></td><td>opens or closes the realtime connection</td></tr><tr><td><a href="/api-reference/realtime.html#joinrealtime"><code>joinRealtime(group:)</code></a></td><td>joins or leaves a group</td></tr><tr><td><a href="/api-reference/realtime.html#postrealtime"><code>postRealtime(_:recipient:notification:)</code></a></td><td>sends to a user or to the group</td></tr><tr><td><a href="/api-reference/realtime.html#getrealtimegroups"><code>getRealtimeGroups(_:fetchOptions:)</code></a> / <a href="/api-reference/realtime.html#getrealtimeusers"><code>getRealtimeUsers(_:fetchOptions:)</code></a></td><td>who is connected where</td></tr><tr><td><a href="/api-reference/realtime.html#realtimeevent"><code>RealtimeEvent</code></a></td><td>what the callback receives</td></tr></tbody></table><h2 id="api-bridge" tabindex="-1"><a href="/api-reference/api-bridge.html">API Bridge</a> <a class="header-anchor" href="#api-bridge" aria-label="Permalink to &quot;[API Bridge](/api-reference/api-bridge)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>method</th><th></th></tr></thead><tbody><tr><td><a href="/api-reference/api-bridge.html#forwardrequest"><code>forwardRequest(_:form:multipart:onStream:)</code></a></td><td>calls another API through Skapi, with your client secrets</td></tr><tr><td><a href="/api-reference/api-bridge.html#forwardrequestpoll"><code>forwardRequestPoll(_:poll:url:method:onStream:service:owner:)</code></a> / <a href="/api-reference/api-bridge.html#forwardrequeststream"><code>forwardRequestStream(_:options:onStream:)</code></a></td><td>waits for a queued or streamed answer</td></tr><tr><td><a href="/api-reference/api-bridge.html#forwardrequestfinalize"><code>forwardRequestFinalize(_:data:options:)</code></a></td><td>stores a streamed request&#39;s final answer</td></tr><tr><td><a href="/api-reference/api-bridge.html#forwardrequesthistory"><code>forwardRequestHistory(_:fetchOptions:)</code></a></td><td>past forwarded requests and their answers</td></tr><tr><td><a href="/api-reference/api-bridge.html#cancelforwardrequest"><code>cancelForwardRequest(_:)</code></a> / <a href="/api-reference/api-bridge.html#forwardrequestqueuecount"><code>forwardRequestQueueCount(_:)</code></a></td><td>queue control</td></tr><tr><td><a href="/api-reference/api-bridge.html#formpart"><code>FormPart</code></a></td><td>one part of a multipart body</td></tr></tbody></table><h2 id="tickets" tabindex="-1"><a href="/api-reference/tickets.html">Tickets</a> <a class="header-anchor" href="#tickets" aria-label="Permalink to &quot;[Tickets](/api-reference/tickets)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>method</th><th></th></tr></thead><tbody><tr><td><a href="/api-reference/tickets.html#consumeticket"><code>consumeTicket(ticketId:method:data:auth:)</code></a></td><td>calls a ticket</td></tr><tr><td><a href="/api-reference/tickets.html#gettickets"><code>getTickets(_:fetchOptions:)</code></a></td><td>the project&#39;s tickets</td></tr><tr><td><a href="/api-reference/tickets.html#getconsumedtickets"><code>getConsumedTickets(_:fetchOptions:)</code></a></td><td>the user&#39;s own ticket calls</td></tr></tbody></table>',18)])])}const u=t(o,[["render",c]]);export{p as __pageData,u as default};
